import difflib

AUTENTICO, MARCA = "bancosantander.es", "santander"

def parecido(a, b):
    # ratio(): 1.0 = idénticos; 0.0 = nada en común
    return difflib.SequenceMatcher(None, a, b).ratio()

def marca_camuflada(nombre):
    # Mira cada trozo del tamaño de la marca: ¿se parece mucho?
    n = len(MARCA)
    trozos = [nombre[i:i + n] for i in range(len(nombre) - n + 1)]
    return max(parecido(t, MARCA) for t in trozos)

def revisar(dominio):
    nombre, _, pais = dominio.rpartition(".")
    r = parecido(nombre, AUTENTICO.rpartition(".")[0])
    m = marca_camuflada(nombre)
    if dominio == AUTENTICO:
        veredicto = "el auténtico"
    elif r == 1.0:
        veredicto = f"SOSPECHOSO: mismo nombre con .{pais}"
    elif r >= 0.85 or m >= 0.85:
        veredicto = "SOSPECHOSO: imita la marca (typo)"
    else:
        veredicto = "distinto"
    return f"{dominio:19} {r:.2f} marca {m:.2f}  {veredicto}"

# Dominios del tema y uno sin relación (todos de ejemplo)
for d in ["bancosantander.es", "bancosantader.es", "gruposantahder.es",
          "bancosantander.ec", "mitiendaonline.es"]:
    print(revisar(d))
